mapper.select:
select yearstr, count(1) as "yearcount", sum(case when rwState=0 then 1 else 0 end) as "yearhandlecount", sum(case when mon=#{month} then 1 else 0 end) as "monthcount", sum(case when mon=#{month} and rwState=7 then 1 else 0 end) as "monthhandlecount" from ( SELECT as "yearstr", as "mon", Rw_State as rwState from Risk_Warn
and Te_Id = #{teId}
) a group by yearstr having yearstr=#{yaer}

select pro.P_Name as pName, pro.P_Name_History as pNameHistory, con.Con_Name as conName, sec.Sec_Name as secName, c1.C_Name_History as rwFlowCNameHistory, c1.C_Name as rwFlowCName, c1.C_Abbreviation as rwFlowCAbbName, d.D_Name as dName, rwi.Rwi_Name as rwiName, rwi.Rwi_Level as rwiLevel, u.U_Name as rwPmName, rwi.Rwi_Desc as rwiDesc, rwi.Rwi_Problem as rwiProblem, u1.U_Name as personLiable, sf.T_Code as tCode, mn.* from Risk_Warn mn left join Risk_Warn_Index rwi on mn.Rwi_Id=rwi.Rwi_Id left join Pre_Project pro on mn.P_Id=pro.P_ID left join Con_Contract con on mn.Con_Id=con.Con_Id left join Sec_Info sec on mn.Sec_Id=sec.Sec_Id left join SYS_Company c1 on mn.Rw_Flow_C_Id=c1.C_Id left join SYS_Department d on mn.D_Id=d.D_Id left join SYS_User u on mn.Rw_Pm_Id=u.U_Id left join SYS_User u1 on mn.Rw_Handle_Uid=u1.U_Id left join SYS_File sf on mn.Rw_From = sf.FileID left join Risk_Warn_Clue clue on mn.Rw_Clue_Id = clue.Rwc_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Rw_Time desc

select t1.D_Name,t1.D_Code,count(1) as "countstr", sum(case when t1.Rw_State=7 then 1 else 0 end) as "Approved", sum(case when t1.Rw_State in(2,9) then 1 else 0 end) as "Approvalfailed", sum(case when t1.Rw_State=0 then 1 else 0 end) as "Pending", sum(case when t1.Rw_State in(1,4) then 1 else 0 end) as "Underapproval" from (select d1.D_Name,d1.D_Code,rw.Rw_State from Risk_Warn rw left join Risk_Warn_Index rwi on rw.Rwi_Id=rwi.Rwi_Id left join (select * from Sys_Dictionary where D_ParentID in( select D_ID from Sys_Dictionary where D_Code='JPMsoft_FXYJDJ')) d1 on rwi.Rwi_Level=d1.D_Code where rw.Rw_Time>=#{params.starttime} and rw.Rw_Time < #{ params.Endtime}
and rwi.Te_Id = #{params.teId}
)t1 group by t1.D_Name,t1.D_Code

select * from(
select t1.Rwi_Id,count(1) as countstr,sum(case when t1.Rw_State=0 then 1 else 0 end) as pending
from ( select * from Risk_Warn where Rw_Time>=#{params.starttime} and Rw_Time < #{ params.Endtime})t1 group
by t1.Rwi_Id
)b1 left join Risk_Warn_Index rwi on b1.Rwi_Id=rwi.Rwi_Id

    
        and rwi.Te_Id = #{params.teId}
    
    
        and rwi.Rwi_Type = #{params.rwiType}
    
    
        and rwi.Rwi_Name like concat('%',#{params.rwiName},'%')
    
    
        and rwi.D_Id = #{params.dId}
    
    
        and rwi.Rwi_Level = #{params.rwiLevel}
    
    
        and rwi.Rwi_Desc like concat('%',#{params.rwiDesc},'%')
    
    
        and rwi.Rwi_Problem like concat('%',#{params.rwiProblem},'%')
    


    order by rwi.${params.sortFiled} ${params.sortType}

limit #{params.start},#{params.size}

select count(1) from(
select t1.Rwi_Id,count(1) as countstr,sum(case when t1.Rw_State=0 then 1 else 0 end) as pending
from ( select * from Risk_Warn where Rw_Time>=#{params.starttime} and Rw_Time < #{ params.Endtime})t1 group
by t1.Rwi_Id
)b1 left join Risk_Warn_Index rwi on b1.Rwi_Id=rwi.Rwi_Id

    
        and rwi.Te_Id = #{params.teId}
    
    
        and rwi.Rwi_Type = #{params.rwiType}
    
    
        and rwi.Rwi_Name like concat('%',#{params.rwiName},'%')
    
    
        and rwi.D_Id = #{params.dId}
    
    
        and rwi.Rwi_Level = #{params.rwiLevel}
    
    
        and rwi.Rwi_Desc like concat('%',#{params.rwiDesc},'%')
    
    
        and rwi.Rwi_Problem like concat('%',#{params.rwiProblem},'%')
    


    order by rwi.${params.sortFiled} ${params.sortType}

select t1.C_Name,t1.C_ID, count(1) as "countstr", sum(case when t1.Rw_State=0 then 1 else 0 end) as "pending" from ( select C_Name,C_ID,RW.Rw_State from Risk_Warn RW left join Pre_Project PP on RW.P_ID=PP.P_Id left join SYS_Company on C_ID=PP.P_Construction_Unit where 1=1
and PP.Te_Id = #{params.teId}
and RW.Rw_Time>=#{params.starttime}
and RW.Rw_Time < #{ params.Endtime}
)t1 group by t1.C_Name,t1.C_ID having 1=1
and t1.C_Name like concat('%',#{params.cName},'%')
and (sum(case when t1.Rw_State=0 then 1 else 0 end) >0 or sum(case when t1.Rw_State in(2,9) then 1 else 0 end)>0 or sum(case when t1.Rw_State in(1,4) then 1 else 0 end)>0)

select t1.P_Name,
count(1) as "countstr",
sum(case when t1.Rw_State=0 then 1 else 0 end) as "pending"
from (
select pp.P_Name,RW.Rw_State from Risk_Warn RW
left join Risk_Warn_Index rwi on RW.Rwi_Id=rwi.Rwi_Id
left join Pre_Project PP on RW.P_ID=PP.P_Id
where 1=1

    and PP.Te_Id = #{params.teId}


    and RW.Rw_Time>=#{params.starttime}


    and RW.Rw_Time < #{ params.Endtime}

)t1 group by t1.P_Name having 1=1

    and t1.P_Name like concat('%',#{params.pName},'%')


    and (sum(case when t1.Rw_State=0 then 1 else 0 end) >0
    or sum(case when t1.Rw_State in(2,9) then 1 else 0 end)>0
    or sum(case when t1.Rw_State in(1,4) then 1 else 0 end)>0)

select t1.C_Name,t1.C_ID, count(1) as "countstr", sum(case when t1.Rw_State=7 then 1 else 0 end) as "approved", sum(case when t1.Rw_State in(2,9) then 1 else 0 end) as "approvalfailed", sum(case when t1.Rw_State=0 then 1 else 0 end) as "pending", sum(case when t1.Rw_State in(1,4) then 1 else 0 end) as "underapproval",
max(t1.Rw_Time) as "rwTime" from ( select RW.Rw_State,C_Name,C_ID,RW.Rw_Time,rwi.Rwi_Level from Risk_Warn RW left join Risk_Warn_Index rwi on RW.Rwi_Id=rwi.Rwi_Id left join Pre_Project PP on RW.P_ID=PP.P_Id left join SYS_Company c1 on c1.C_ID=PP.P_Construction_Unit where 1=1
and PP.Te_Id = #{params.teId}
and RW.Rw_Time>=#{params.starttime}
and RW.Rw_Time < #{ params.Endtime}
)t1 group by t1.C_Name,t1.C_ID having 1=1
and t1.C_Name like concat('%',#{params.cName},'%')
and (sum(case when t1.Rw_State=0 then 1 else 0 end) >0 or sum(case when t1.Rw_State in(2,9) then 1 else 0 end)>0 or sum(case when t1.Rw_State in(1,4) then 1 else 0 end)>0)
limit #{params.start},#{params.size}

select t1.P_Name, count(1) as "countstr", sum(case when t1.Rw_State=7 then 1 else 0 end) as "approved", sum(case when t1.Rw_State in(2,9) then 1 else 0 end) as "approvalfailed", sum(case when t1.Rw_State=0 then 1 else 0 end) as "pending", sum(case when t1.Rw_State in(1,4) then 1 else 0 end) as "underapproval",
max(t1.Rw_Time) as "rwTime" from ( select PP.P_Name,RW.Rw_State,RW.Rw_Time,rwi.Rwi_Level from Risk_Warn RW left join Risk_Warn_Index rwi on RW.Rwi_Id=rwi.Rwi_Id left join Pre_Project PP on RW.P_ID=PP.P_Id where 1=1
and PP.Te_Id = #{params.teId}
and RW.Rw_Time>=#{params.starttime}
and RW.Rw_Time < #{ params.Endtime}
)t1 group by t1.P_Name having 1=1
and t1.P_Name like concat('%',#{params.pName},'%')
and (sum(case when t1.Rw_State=0 then 1 else 0 end) >0 or sum(case when t1.Rw_State in(2,9) then 1 else 0 end)>0 or sum(case when t1.Rw_State in(1,4) then 1 else 0 end)>0)
limit #{params.start},#{params.size}

select pro.P_Name as pName, pro.P_Name_History as pNameHistory, con.Con_Name as conName, sec.Sec_Name as secName, c1.C_Name_History as rwFlowCNameHistory, c1.C_Name as rwFlowCName, c1.C_Abbreviation as rwFlowCAbbName, d.D_Name as dName, rwi.Rwi_Name as rwiName, rwi.Rwi_Level as rwiLevel, u.U_Name as rwPmName, rwi.Rwi_Desc as rwiDesc, rwi.Rwi_Problem as rwiProblem, u1.U_Name as personLiable, mn.*, opr.Opl_Id as oplId, sf.T_Code as tCode from Risk_Warn mn left join Risk_Warn_Index rwi on mn.Rwi_Id=rwi.Rwi_Id left join Pre_Project pro on mn.P_Id=pro.P_ID left join Con_Contract con on mn.Con_Id=con.Con_Id left join Sec_Info sec on mn.Sec_Id=sec.Sec_Id left join SYS_Company c1 on mn.Rw_Flow_C_Id=c1.C_Id left join SYS_Department d on mn.D_Id=d.D_Id left join SYS_User u on mn.Rw_Pm_Id=u.U_Id left join SYS_User u1 on mn.Rw_Handle_Uid=u1.U_Id left join Outline_Project_Risk opr on opr.Risk_Id = mn.Rwi_Id left join SYS_File sf on mn.Rw_From = sf.FileID left join Risk_Warn_Clue clue on mn.Rw_Clue_Id = clue.Rwc_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Rw_Time desc
